  ellipsoid('haunch',leg,[x,1.12,-.015],[.38,.59,.39],gold,950);
  limb('thigh',leg,[x,1.04,.06],[x+side*.055,.56,.26],.285,.315,gold,650);
  ellipsoid('knee',leg,[x+side*.055,.59,.27],[.285,.30,.30],armGold,450);
  limb('shin',leg,[x+side*.055,.57,.23],[x+side*.035,.04,.035],.235,.24,gold,650);
  ellipsoid('foot',leg,[x+side*.045,.035,.20],[.26,.14,.39],gold,250);
}

const arms=group('arms',creature);
