ellipsoid('shoulder',leftArm,[-.66,2.79,-.015],[.40,.49,.41],armGold,1000);
limb('upper-arm',leftArm,[-.78,2.72,.025],[-.94,2.03,.105],.29,.30,armGold,1000);
ellipsoid('elbow',leftArm,[-.91,1.99,.12],[.26,.29,.265],armGold,450);
limb('forearm',leftArm,[-.92,2.04,.12],[-.75,1.25,.43],.22,.24,armGold,900);
ellipsoid('wrist-fur',leftArm,[-.755,1.26,.43],[.18,.21,.19],gold,350);

const rightArm=group('right-arm',arms);
ellipsoid('shoulder',rightArm,[.65,2.79,-.035],[.43,.50,.43],armGold,1100);
