ellipsoid('elbow',rightArm,[1.08,1.99,.07],[.335,.35,.335],armGold,650);
limb('forearm',rightArm,[1.08,2.00,.08],[.85,1.23,.43],.275,.29,armGold,1150);
ellipsoid('wrist-fur',rightArm,[.85,1.25,.43],[.205,.22,.205],gold,400);

function makeHand(parent,name,x,y,z,side){
  const hand=group(name,parent);
  hand.position.set(x,y,z);
  hand.rotation.z=side*.10;
  ellipsoid('palm',hand,[0,-.075,.015],[.185,.235,.104],handMat);
  ellipsoid('knuckles',hand,[0,-.19,.048],[.19,.095,.098],handMat);
  const fingerLengths=[.245,.31,.30,.225];
  const fingerXs=[-.125,-.043,.045,.124];
  for(let i=0;i<4;i++){
    const fg=group('finger-'+(i+1),hand);
    const fx=fingerXs[i];
    const len=fingerLengths[i];
    const spread=fx*.22;
    const pts=[
      [fx,-.17,.065],
      [fx+spread*.5,-.17-len*.38,.107],
      [fx+spread,-.17-len*.80,.12],
      [fx+spread,-.17-len,.09]
    ];
    curveTube('finger',fg,pts,.039-(i===3?.005:0),fingerMat,14);
    ellipsoid('fingertip',fg,pts[3],[.035,.046,.037],fingerMat);
    ellipsoid('small-dark-nail',fg,[fx+spread,-.17-len+.017,.122],[.024,.045,.009],nailMat);
  }
  const tx=-side*.158;
  curveTube('thumb',hand,[
    [tx,-.04,.05],
    [tx-side*.08,-.13,.12],
    [tx-side*.075,-.245,.155],
    [tx-side*.02,-.28,.155]
  ],.055,handMat,16);
  ellipsoid('thumb-tip',hand,[tx-side*.02,-.28,.155],[.05,.061,.047],fingerMat);
  return hand;
}
makeHand(leftArm,'left-hand',-.735,1.20,.54,-1);
makeHand(rightArm,'right-hand',.80,1.18,.56,1);

const head=group('head',creature);
head.position.set(-.035,3.485,.015);
head.rotation.z=-.165;
head.rotation.x=-.075;

const RX=.525,RY=.69,RZ=.455;
const mouthRX=.327,mouthRY=.402,mouthCY=-.084;
function mouthBoundary(a){
  const s=Math.sin(a),c=Math.cos(a);
  return new THREE.Vector2(mouthRX*c*(1+.075*s),mouthCY+mouthRY*s);
}
function faceZ(x,y){
  return RZ*Math.sqrt(Math.max(.005,1-x*x/(RX*RX)-y*y/(RY*RY)));
}
{
  const positions=[],indices=[],n=96,nr=25;
  for(let r=0;r<=nr;r++){
    const t=r/nr;
    for(let j=0;j<=n;j++){
      const a=j/n*Math.PI*2;
      const inner=mouthBoundary(a);
      const x=inner.x*(1-t)+RX*Math.cos(a)*t;
      const y=inner.y*(1-t)+RY*Math.sin(a)*t;
      positions.push(x,y,faceZ(x,y));
    }
  }
  for(let r=0;r<nr;r++)for(let j=0;j<n;j++){
    const a=r*(n+1)+j,c=a+n+1;
    indices.push(a,c,a+1,a+1,c,c+1);
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
  geo.setIndex(indices);geo.computeVertexNormals();
  const mesh=new THREE.Mesh(geo,headGold);
  mesh.castShadow=true;mesh.receiveShadow=true;
  mesh.name='face-around-open-mouth';
  head.add(mesh);

  const bp=[],bi=[];
  for(let r=0;r<=nr;r++){
    const t=r/nr;
    for(let j=0;j<=n;j++){
      const a=j/n*Math.PI*2;
      bp.push(RX*t*Math.cos(a),RY*t*Math.sin(a),-RZ*Math.sqrt(Math.max(0,1-t*t)));
    }
  }
  for(let r=0;r<nr;r++)for(let j=0;j<n;j++){
    const a=r*(n+1)+j,c=a+n+1;
    bi.push(a,a+1,c,a+1,c+1,c);
  }
  const bg=new THREE.BufferGeometry();
  bg.setAttribute('position',new THREE.Float32BufferAttribute(bp,3));
  bg.setIndex(bi);bg.computeVertexNormals();
  const back=new THREE.Mesh(bg,headGold);
  back.name='back-of-head';back.castShadow=true;back.receiveShadow=true;
  head.add(back);
}
fur(head,[RX,RY,RZ],2100,'#e8c33d',(v,n)=>{
  if(n.z<.15)return true;
  const q=v.x*v.x/(.40*.40)+(v.y-mouthCY)*(v.y-mouthCY)/(.51*.51);
  return q>1.20 && v.y>.25;
},.020);

const mouth=group('wide-open-laughing-mouth',head);
{
  const positions=[],indices=[],n=96,nr=18;
  for(let r=0;r<=nr;r++){
    const t=r/nr;
    for(let j=0;j<=n;j++){
      const a=j/n*Math.PI*2,p=mouthBoundary(a);
      const x=p.x*t;
      const y=mouthCY+(p.y-mouthCY)*t;
      const z=faceZ(p.x,p.y)-.335*(1-t*t)-.008;
      positions.push(x,y,z);
    }
  }
  for(let r=0;r<nr;r++)for(let j=0;j<n;j++){
    const a=r*(n+1)+j,c=a+n+1;
    indices.push(a,c,a+1,a+1,c,c+1);
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
  geo.setIndex(indices);geo.computeVertexNormals();
  const cavity=new THREE.Mesh(geo,mouthMat);
  cavity.name='deep-dark-mouth-cavity';mouth.add(cavity);

  const points=[];
  for(let j=0;j<=96;j++){
    const a=j/96*Math.PI*2,p=mouthBoundary(a);
    points.push([p.x,p.y,faceZ(p.x,p.y)+.007]);
  }
  curveTube('golden-mouth-rim',mouth,points,.023,lipMat,96);
}
const teeth=group('upper-teeth',mouth);
for(let i=0;i<7;i++){
  const x=(i-3)*.072;
  const y=.212-.076*Math.pow(x/.25,2);
  const z=faceZ(x,y)-.026;
  const tooth=new THREE.Mesh(new RoundedBoxGeometry(.073,.098,.067,2,.012),toothMat);
  tooth.position.set(x,y-.022,z);
  tooth.rotation.z=-x*.47;
