}
curveTube('upper-gum-shadow',mouth,[
  [-.265,.157,.325],[-.17,.224,.374],[0,.247,.410],[.17,.224,.374],[.265,.157,.325]
],.018,new THREE.MeshStandardMaterial({color:'#7b561d',roughness:1}),32);

const lowerTeeth=group('lower-teeth',mouth);
for(let i=0;i<5;i++){
  const x=-.135+i*.053;
