}
ellipsoid('tongue-in-shadow',mouth,[-.025,-.345,.145],[.115,.042,.075],
  new THREE.MeshStandardMaterial({color:'#6b3a1c',roughness:1}));
curveTube('lower-inner-lip',mouth,[
  [-.22,-.36,.264],[-.14,-.447,.289],[-.015,-.476,.302],[.11,-.437,.29],[.19,-.36,.27]
],.018,new THREE.MeshStandardMaterial({color:'#b38638',roughness:1}),28);

const eyes=group('closed-laughing-eyes',head);
function closedEye(name,cx,cy,width){
  const eg=group(name,eyes);
  const pts=[];
  for(let i=0;i<=16;i++){
    const t=i/16,x=cx+(t-.5)*width;
    const y=cy+.060*Math.sin(t*Math.PI);
    pts.push([x,y,faceZ(x,y)+.016]);
  }
  curveTube('closed-eyelid',eg,pts,.018,eyeMat,24);
  const fold=[];
  for(let i=0;i<=14;i++){
    const t=i/14,x=cx+(t-.5)*width*1.1;
    const y=cy+.035+.058*Math.sin(t*Math.PI);
    fold.push([x,y,faceZ(x,y)+.012]);
  }
  curveTube('raised-golden-eyelid',eg,fold,.026,headGold,24);
}
closedEye('left-eye',-.298,.405,.217);
closedEye('right-eye',.292,.372,.205);

ellipsoid('subtle-nose-bridge',head,[0,.342,.389],[.093,.052,.041],headGold);
ellipsoid('left-cheek',head,[-.36,-.01,.256],[.075,.19,.066],headGold,120,'#dcb02a');
ellipsoid('right-cheek',head,[.36,-.01,.256],[.075,.19,.066],headGold,120,'#dcb02a');

